import os
from collections import namedtuple
from typing import Optional

from robot.errors import DataError

from .config import Config, ConfigsStore
from .qc import QCInstance
from ..utils.logger import logger
from ..utils.tags import (
    get_single_tag_from_test,
    get_tags_from_suite_force_tags,
)

from ..robot_compatibility import TestData


class Reader:

    def __init__(
            self,
            robot_path: str,
            sw_version: str,
            qc_config_path: Optional[str] = None,
            label: Optional[str] = None,
            no_qc: Optional[bool] = None,
    ):
        """
        :param string       robot_path:      Path to robot file location
        :param string       sw_version:      Version of eNB software, e.g. FL00 or LN7.0
        :param string       qc_config_path:  Path to qc configuration file location
        """
        self._robot_path = robot_path
        self._sw_version = sw_version
        self._qc_config_path = self._set_qc_config_path(qc_config_path)
        self._label = label
        self._no_qc = no_qc

    def __iter__(self):
        return (each for each in self._visit_robot_file())

    def _set_qc_config_path(self, qc_config_path: str):
        return (
            qc_config_path if qc_config_path
            else str(self._robot_path).replace(".robot", ".qc")
        )

    def get_qc_instance(self, test_name: str):
        """Creating QC instance object with all the parameters

        :param string       test_name:         Name of test for which tag will be searched.

        :return: QC_Instance object
        :rtype: QCInstance
        """
        if self._no_qc:
            return [QCInstance()]
        test_instance_id, qc_domain, qc_project, multi_report = (
            self.get_qc_info_from_robot_file(test_name)
        )
        path_set_pairs, _ = self._get_qc_config_items(test_name)
        if not multi_report:
            path_set_pairs = path_set_pairs[:1]
        qc_instances = []
        for paths_entry in path_set_pairs:
            qc_instances.append(
                QCInstance(
                    test_instance_name=test_name,
                    test_lab_path=paths_entry["qc_path"],
                    test_set_name=paths_entry["qc_test_set"],
                    test_instance_id=test_instance_id,
                    qc_domain=qc_domain,
                    qc_project=qc_project,
                )
            )
        return qc_instances

    def _get_qc_config_items(self, test_name: str):
        if not os.path.exists(self._qc_config_path):
            return [{"qc_path": "", "qc_test_set": ""}], False
        with open(self._qc_config_path) as f:
            cfg = Config(f.read())
            cfg.validate()
            return cfg.get_qc(
                self._sw_version, test_name, self._label, self._robot_path
            )

    def read_test_cases_configs(self):
        """Return list of configs for test cases in test suite

        :return: List of configs
        :rtype: ConfigsStore
        """
        suite = self._create_suite()
        test_cases = [test.name for test in suite.testcase_table]
        configs = []
        for test_case in test_cases:
            configs.append(self.get_qc_instance(test_case))
        return ConfigsStore(configs)

    def get_qc_info_from_robot_file(self, test_name: str):
        """Getting QC_ID tag from robot suite file

        :param string       test_name:      Name of test for which tag will be searched.

        :return: Value of QC_id TAG.
        :rtype: string.
        """
        if os.path.exists(self._robot_path):
            suite = self._create_suite()
            return (
                self._get_qc_info_from_suite(suite, test_name)
                if suite
                else (None, "", "", False)
            )
        else:
            return None, "", "", False

    def _create_suite(self):
        try:
            return TestData(source=self._robot_path)
        except DataError:
            return None

    def _get_qc_info_from_suite(self, suite, test_name):
        multi_report = None
        test_instance_id = None
        qc_domain = ""
        qc_project = ""
        for test in suite.testcase_table:
            if (test_name in test.name) and test.tags:
                test_instance_id = get_single_tag_from_test(test, "QC")
                multi_report = True if get_single_tag_from_test(test, "MQC") else False
                qc_domain = (
                    get_single_tag_from_test(test, "QCD")
                    or get_tags_from_suite_force_tags(suite, "QCD")
                    or ""
                )
                qc_project = (
                    get_single_tag_from_test(test, "QCP")
                    or get_tags_from_suite_force_tags(suite, "QCP")
                    or ""
                )
        if not (test_instance_id and qc_domain and qc_project):
            logger.debug(
                "All of QC_id, QCD_domain and QCP_project are necessary. One or more are not set."
            )
        return test_instance_id, qc_domain, qc_project, multi_report

    def _visit_robot_file(self):
        test_set = []
        suite = self._create_suite()
        if suite:
            for test in suite.testcase_table:
                test_instance_name = test.name
                test_lab_path, test_set_name = self._get_qc_config_items(
                    test_instance_name
                )
                test_instance_id = None
                for tag in test.tags:
                    if "QC_" in tag:
                        test_instance_id = str(tag).replace("QC_", "")
                named_tuple = self._create_named_tuple(
                    (
                        str(test.name),
                        test_set_name,
                        test_instance_name,
                        test_lab_path,
                        test_instance_id,
                    )
                )
                test_set.append(named_tuple)
            return test_set
        else:
            logger.debug("No test cases found")
            return test_set

    def _create_named_tuple(self, test_set):
        TestQCInstance = namedtuple(
            "TestQCInstance",
            [
                "test_name",
                "test_set_name",
                "test_instance_name",
                "test_lab_path",
                "test_instance_id",
            ],
        )
        return TestQCInstance(*test_set)
